// Helper function to compute the payoff at maturity (log-space)
std::vector<double> payoff_maturity_logspace(Kind kind, double K, double S, int nS) {
    std::vector<double> payoff(nS);
    double log_K = std::log(K);
    double log_S = std::log(S);

    // Use a log-grid that covers the relevant range
    double log_S_min = log_K - 3.0;  // 3 standard deviations
    double log_S_max = log_K + 3.0;
    double dlog_S = (log_S_max - log_S_min) / (nS - 1);

    for (int i = 0; i < nS; ++i) {
        double log_S_i = log_S_min + i * dlog_S;
        double S_i = std::exp(log_S_i);
        payoff[i] = payoff(kind, S_i, K);
    }

    return payoff;
